#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <gnuradio/wifi_ofdm/ppdu_builder.h>
// pydoc.h is automatically generated in the build directory
#include <ppdu_builder_pydoc.h>

void bind_ppdu_builder(py::module& m)
{

    using ppdu_builder = gr::wifi_ofdm::ppdu_builder;


    py::class_<ppdu_builder, gr::block, gr::basic_block, std::shared_ptr<ppdu_builder>>(
        m, "ppdu_builder", D(ppdu_builder))

        .def(py::init(&ppdu_builder::make),
             py::arg("seed"),
             py::arg("rate"),
             D(ppdu_builder, make))

        .def("set_ppdu_rate",
             &ppdu_builder::set_ppdu_rate,
             py::arg("rate"),
             "Set the PPDU rate dynamically.") // NOTE: dropping Doxygen MACRO

        ;
}
